#include <bits/stdc++.h>
using namespace std;
vector<int> nextGreater(vector<int>& a) {
    int n = a.size();
    vector<int> ans(n, -1);
    stack<int> st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.top()] < a[i]) {
            ans[st.top()] = a[i]; st.pop();
        }
        st.push(i);
    }
    return ans;
}

