func nextGreater(a []int) []int {
    n := len(a)
    ans := make([]int, n)
    for i := range ans { ans[i] = -1 }
    st := []int{}
    for i, x := range a {
        for len(st) > 0 && a[st[len(st)-1]] < x {
            ans[st[len(st)-1]] = x
            st = st[:len(st)-1]
        }
        st = append(st, i)
    }
    return ans
}
